# Tab completion for offroad-autonomy and the repository scripts, in Bash.
# Generated by scripts/generate_completions.py from the argparse parsers:
# regenerate it after changing an option instead of editing it.
#
#   source completions/offroad-autonomy.bash    # add to ~/.bashrc to keep it
#
# Scripts complete after `python` or `python3`. Any other python command line
# falls back to file names, which replaces bash-completion's own completion of
# the interpreter's flags in shells that source this file.

_offroad_scripts="benchmark_display_padding.py benchmark_planning.py benchmark_postprocess.py benchmark_rgb.py check_brake_hold.py closed_loop_log.py compare_benchmarks.py compare_control_logs.py derive_ego_mask.py diagnose_perception.py export_engine.py generate_completions.py sbend_sim.py"

_offroad_spec() {
    _offroad_opts=""
    _offroad_values=""
    _offroad_subs=""
    _offroad_positional=""
    case "$1" in
        benchmark_display_padding.py)
            _offroad_opts="-h --help --out --iterations"
            _offroad_values="--out=file --iterations=none"
            ;;
        benchmark_planning.py)
            _offroad_opts="-h --help --out --half-width-m"
            _offroad_values="--out=file --half-width-m=none"
            ;;
        benchmark_postprocess.py)
            _offroad_opts="-h --help --baseline-root --labels --out"
            _offroad_values="--baseline-root=file --labels=file --out=file"
            ;;
        benchmark_rgb.py)
            _offroad_opts="-h --help --config --images --labels --label-suffix --out --limit --input-size --working-size --weights --half --no-half --threshold --clahe --morphology --ema --render-ui --road-value --void-value --timestamp-scale --sequence-gap-s --warmup --planning"
            _offroad_values="--config=file --images=file --labels=file --label-suffix=file --out=file --limit=none --input-size=none --working-size=none --weights=file --threshold=none --road-value=none --void-value=none --timestamp-scale=none --sequence-gap-s=none --warmup=none"
            ;;
        check_brake_hold.py)
            _offroad_opts="-h --help --config --reproduce-arcade --out"
            _offroad_values="--config=file --out=file"
            ;;
        closed_loop_log.py)
            _offroad_opts="-h --help --config --seconds --out --snap-from --summary"
            _offroad_values="--config=file --seconds=none --out=file --snap-from=none"
            ;;
        compare_benchmarks.py)
            _offroad_opts="-h --help --markdown"
            _offroad_positional=1
            ;;
        compare_control_logs.py)
            _offroad_opts="-h --help --out"
            _offroad_values="--out=file"
            _offroad_positional=1
            ;;
        derive_ego_mask.py)
            _offroad_opts="-h --help --config --margin-px --epsilon --close-px"
            _offroad_values="--config=file --margin-px=none --epsilon=none --close-px=none"
            ;;
        diagnose_perception.py)
            _offroad_opts="-h --help --config"
            _offroad_values="--config=file"
            _offroad_subs="capture analyze full"
            ;;
        diagnose_perception.py:analyze)
            _offroad_opts="-h --help --src --out --side --conf --weights --no-clahe"
            _offroad_values="--src=file --out=file --side=choice:dashcam --conf=none --weights=file"
            ;;
        diagnose_perception.py:capture)
            _offroad_opts="-h --help --out --frames --spawn"
            _offroad_values="--out=file --frames=none --spawn=none"
            ;;
        diagnose_perception.py:full)
            _offroad_opts="-h --help --src --out"
            _offroad_values="--src=file --out=file"
            ;;
        export_engine.py)
            _offroad_opts="-h --help --config --weights --fp32"
            _offroad_values="--config=file --weights=file"
            ;;
        generate_completions.py)
            _offroad_opts="-h --help"
            ;;
        offroad-autonomy)
            _offroad_opts="-h --help --config --weights --road-class --log-level --headless --benchmark-seconds --benchmark-warmup --benchmark-out --label --record-video --record-video-out --presentation --presentation-view --presentation-out"
            _offroad_values="--config=file --weights=file --road-class=file --log-level=choice:DEBUG|INFO|WARNING|ERROR --benchmark-seconds=none --benchmark-warmup=none --benchmark-out=file --label=file --record-video-out=file --presentation-out=file"
            ;;
        sbend_sim.py)
            _offroad_opts="-h --help --config --radius --fps --verbose"
            _offroad_values="--config=file --radius=none --fps=none"
            ;;
    esac
}

_offroad_value_kind() {
    local pair
    _offroad_kind=""
    for pair in $_offroad_values; do
        if [[ "${pair%%=*}" == "$1" ]]; then
            _offroad_kind="${pair#*=}"
            return 0
        fi
    done
    return 1
}

_offroad_complete_value() {
    case "$1" in
        file)
            compopt -o filenames 2>/dev/null
            mapfile -t COMPREPLY < <(compgen -f -- "$2")
            ;;
        choice:*)
            local choices="${1#choice:}"
            mapfile -t COMPREPLY < <(compgen -W "${choices//|/ }" -- "$2")
            ;;
    esac
}

# $1 is the spec key, $2 the index of the first word after the command.
_offroad_complete_from() {
    local key="$1" i="$2" word cur="${COMP_WORDS[COMP_CWORD]}"
    _offroad_spec "$key"
    while (( i < COMP_CWORD )); do
        word="${COMP_WORDS[i]}"
        if _offroad_value_kind "$word"; then
            if (( i + 1 == COMP_CWORD )); then
                _offroad_complete_value "$_offroad_kind" "$cur"
                return
            fi
            # Skip the value too, so a value spelled like a subcommand is not
            # taken for one.
            i=$((i + 2))
            continue
        fi
        if [[ " $_offroad_subs " == *" $word "* ]]; then
            key="$key:$word"
            _offroad_spec "$key"
        fi
        i=$((i + 1))
    done
    if [[ "$cur" != -* && -n "$_offroad_subs" ]]; then
        mapfile -t COMPREPLY < <(compgen -W "$_offroad_subs" -- "$cur")
        return
    fi
    if [[ "$cur" != -* && -n "$_offroad_positional" ]]; then
        _offroad_complete_value file "$cur"
        return
    fi
    mapfile -t COMPREPLY < <(compgen -W "$_offroad_opts" -- "$cur")
}

_offroad_autonomy_complete() {
    COMPREPLY=()
    _offroad_complete_from offroad-autonomy 1
}

_offroad_python_complete() {
    COMPREPLY=()
    local script="${COMP_WORDS[1]##*/}"
    if (( COMP_CWORD >= 2 )) && [[ " $_offroad_scripts " == *" $script "* ]]; then
        _offroad_complete_from "$script" 2
        return
    fi
    compopt -o default 2>/dev/null
}

complete -F _offroad_autonomy_complete offroad-autonomy
complete -F _offroad_python_complete python python3
